internal sealed class StatementBuilderServices
{
    public StatementBuilderServices()
    {
        var contacts = new Dictionary<string, string>(StringComparer.Ordinal);
        Statements = new StatementComposer(new List<string>(), contacts);
        Amounts = new AmountFormatter(new Dictionary<decimal, string>());
        Contacts = new ContactResolver(contacts);
